document.getElementById('dialog-open').onclick=()=>obUI.openDialog('demo-dialog');document.getElementById('toast-open').onclick=()=>obUI.toast('Changes saved for this preview.');document.querySelectorAll('[role=tab]').forEach(t=>t.onclick=()=>{document.querySelectorAll('[role=tab]').forEach(x=>x.setAttribute('aria-selected',String(x===t)));document.getElementById('tab-content').textContent=t.textContent==='Active'?'Original sample video · 42%':'No finished downloads'});document.getElementById('pause').onclick=e=>{e.target.textContent=e.target.textContent==='Pause download'?'Resume download':'Pause download'};